import tempfile
import torch
import torch.nn as nn
import torch.nn.functional as F
from topologies import Trainer, build, synth
root = tempfile.mkdtemp()
@synth.generator
def samples(ctx):
    return {"inputs": synth.Tensor(torch.randn(4, generator=ctx.rng.torch))}
dataset = synth.Spec("ctc-attention", generator=samples, size=8, splits={"train": 1.0}, seed=7, root=root, monitor="none").run()
train = dataset.for_recipe("structured-objective", split="train")
class JointLossModel(nn.Module):
    def __init__(self):
        super().__init__()
        self.network = build("mlp", "tiny", in_features=4, out_features=2)
    def forward(self, inputs):
        components = F.softplus(self.network(inputs))
        return {"ctc_nll": components[:, 0], "attention_nll": components[:, 1]}
trainer = Trainer(JointLossModel(), train, recipe="structured-objective", recipe_config={"loss": "ctc-attention", "loss_kwargs": {"ctc_weight": 0.2}, "bindings": {"logits_or_prediction": {"output": "ctc_nll"}, "targets": {"output": "attention_nll"}}}, batch_size=4, max_epochs=1, device="cpu")
trainer.fit()
